"""Finish a manifest freshly generated by `rexglue init` (used by `rex new`).

  newproject.py <manifest> <xex>

- adds a header comment identifying the game (title ID, version, entry,
  SHA-256 of the XEX) so a changed/different dump is noticed later;
- appends an [entrypoint.functions] table as the LAST table, which is where
  `rex triage` appends functions that static analysis missed.
Also usable alone: `newproject.py --info <xex>` prints the XEX header info.
"""
import hashlib
import struct
import sys
from pathlib import Path


def xex_info(path: Path) -> dict:
    d = path.read_bytes()
    if d[:4] != b"XEX2":
        raise SystemExit(f"{path}: not an XEX2 file")
    n = struct.unpack(">I", d[20:24])[0]
    info = {"sha256": hashlib.sha256(d).hexdigest()}
    for i in range(n):
        key, val = struct.unpack(">II", d[24 + i * 8:32 + i * 8])
        if key == 0x00040006:  # execution info
            _, ver, _, tid = struct.unpack(">IIII", d[val:val + 16])
            info["title_id"] = f"{tid:08X}"
            info["version"] = ver
        elif key == 0x00010100:
            info["entry"] = f"0x{val:08X}"
        elif key == 0x00010201:
            info["image_base"] = f"0x{val:08X}"
    return info


FUNCS_BLOCK = """
# Function boundaries static analysis missed (vtable-only / tail-branch-only
# targets). Empty table = let the analyzer auto-detect the extent. Codegen
# reports some as "UnresolvedCall ... target not in any function"; the rest
# show up at runtime and `rex triage` appends them. Keep this table LAST.
[entrypoint.functions]
"""


def main():
    if sys.argv[1] == "--info":
        for k, v in xex_info(Path(sys.argv[2])).items():
            print(f"{k}: {v}")
        return
    manifest, xex = Path(sys.argv[1]), Path(sys.argv[2])
    info = xex_info(xex)
    text = manifest.read_text()
    header = (
        f"# Title ID {info.get('title_id', '?')}, XEX version {info.get('version', '?')}, "
        f"entry {info.get('entry', '?')}, image base {info.get('image_base', '?')}\n"
        f"# {xex.name} SHA-256 {info['sha256']}\n"
    )
    if "SHA-256" not in text:
        lines = text.splitlines(keepends=True)
        insert_at = 1 if lines and lines[0].startswith("#") else 0
        text = "".join(lines[:insert_at]) + header + "".join(lines[insert_at:])
    if "[entrypoint.functions]" not in text:
        text = text.rstrip("\n") + "\n" + FUNCS_BLOCK
    manifest.write_text(text)
    print(header, end="")


if __name__ == "__main__":
    main()
